-- Every historical Recon Summary was generated by the Ollama-only pipeline.
ALTER TABLE "ReconSummary" ADD COLUMN "provider" "AiProvider" NOT NULL DEFAULT 'OLLAMA';

-- Resolve only invalid historical concurrent activations before enforcing the
-- invariant. Keep the most recently edited configuration, with a stable tie.
WITH ranked AS (
  SELECT id, row_number() OVER (PARTITION BY "userId" ORDER BY "updatedAt" DESC, id DESC) AS position
  FROM "AiProviderConfig" WHERE "isActive" = true
)
UPDATE "AiProviderConfig" SET "isActive" = false
WHERE id IN (SELECT id FROM ranked WHERE position > 1);

CREATE UNIQUE INDEX "AiProviderConfig_one_default_per_user"
ON "AiProviderConfig" ("userId") WHERE "isActive" = true;
